async function boundProject(page: Page, prefix: string) {
  const name = `${prefix} ${randomUUID().slice(0, 8)}`;
  await page.goto("/projects/new");
  await page.getByLabel("Nom du projet", { exact: true }).fill(name);
  await page.getByRole("button", { name: "Enregistrer le projet", exact: true }).click();
  await expect(page.getByRole("heading", { name, exact: true })).toBeVisible();
  const projectId = page.url().split("/").at(-1);
  if (!projectId) throw new Error("Synthetic delivery browser project missing");
  await page.getByLabel("Dépôt", { exact: true }).fill("fixture/browser-delivery");
  await page.getByLabel("ID du dépôt", { exact: true }).fill("12345");
  await page.getByLabel("ID de l’installation GitHub App", { exact: true }).fill("67890");
  await page.getByLabel("Branche suivie", { exact: true }).fill("main");
  await page.getByRole("button", { name: "Enregistrer l’association", exact: true }).click();
  await expect(
    page.getByText("Association enregistrée localement.", { exact: true }),
  ).toBeVisible();
  await page.goto("/pipelines");
  await expect(
    page.getByRole("heading", { name: "Déploiements des sites et back-ends", exact: true }),
  ).toBeVisible();
  await page.getByRole("combobox", { name: "Projet", exact: true }).selectOption({ label: name });
  return {
    name,
    projectId,
    form: page.getByRole("form", { name: "Créer une politique de livraison", exact: true }),
  };
}
const policyCard = (page: Page, name: string) =>
  page
    .locator(".operation-row")
    .filter({ hasText: name })
    .filter({ has: page.getByRole("button", { name: "Révoquer", exact: true }) });
async function createPolicy(page: Page, form: ReturnType<Page["getByRole"]>) {
  const response = page.waitForResponse(
    (result) =>
      new URL(result.url()).pathname.endsWith("/delivery/policies") &&
      result.request().method() === "POST",
  );
  await form.getByRole("button", { name: "Enregistrer la politique", exact: true }).click();
  expect((await response).status()).toBe(201);
}

async function expectWholeAction(button: Locator) {
  await button.scrollIntoViewIfNeeded();
  const bounds = await button.evaluate((element) => {
    const rect = element.getBoundingClientRect();
    const contains = (left: number, right: number) =>
      rect.left >= left - 1 && rect.right <= right + 1;
    let unclipped = true;
    for (let parent = element.parentElement; parent; parent = parent.parentElement) {
      if (getComputedStyle(parent).overflowX !== "visible") {
        const clip = parent.getBoundingClientRect();
        unclipped &&= contains(clip.left, clip.right);
      }
    }
    const contents = document.createRange();
    contents.selectNodeContents(element);
    const textFits = Array.from(contents.getClientRects()).every(
      (content) => content.left >= rect.left - 1 && content.right <= rect.right + 1,
    );
    return { inViewport: contains(0, innerWidth), unclipped, textFits };
  });
  expect(bounds).toEqual({ inViewport: true, unclipped: true, textFits: true });
}

test("T-AC-45 T-AC-51 creates, persists and revokes exact synthetic standing policy while default execution remains unavailable", async ({
  page,
}) => {
  const project = await boundProject(page, "Delivery desktop");
  await expect(
    page.getByRole("heading", { name: "Exécution des déploiements indisponible", exact: true }),
  ).toBeVisible();
  await expect(page.getByText(/La GitHub App n’est pas connectée/)).toBeVisible();
  await project.form.getByLabel(/Autoriser la livraison automatique compatible/).check();
  await createPolicy(page, project.form);
  const card = policyCard(page, project.name);
  await expect(card.getByText(/Automatique sous contrôles/)).toBeVisible();
  await expect(
    card.getByRole("button", { name: "Synchroniser GitHub", exact: true }),
  ).toBeDisabled();
  await page.reload();
  await expect(card).toBeVisible();
  await page.screenshot({ path: "artifacts/delivery-overview.png", fullPage: true });
  await card.getByRole("button", { name: "Révoquer", exact: true }).click();
  await expect(card.getByText(/Révoquée/)).toBeVisible();
  await expect(card.getByRole("button", { name: "Révoquer", exact: true })).toBeDisabled();
  await expect(page.getByText("Aucune livraison préparée", { exact: true })).toBeVisible();
});

