test("T-AC-45 T-AC-51 keeps finite mobile policy forms and rejects browser execution fields without leaking values", async ({
  page,
}) => {
  await page.setViewportSize({ width: 390, height: 844 });
  const project = await boundProject(page, "Delivery mobile");
  await expect(
    project.form.getByLabel("Previews simultanées maximum", { exact: true }),
  ).toHaveAttribute("max", "8");
  await expect(
    project.form.getByLabel("Durée d’une preview (heures)", { exact: true }),
  ).toHaveAttribute("max", "720");
  await project.form
    .getByRole("combobox", { name: "Type d’application", exact: true })
    .selectOption("node");
  await createPolicy(page, project.form);
  await expect(policyCard(page, project.name).getByText(/Back-end Node.js/)).toBeVisible();
  const marker = `private-command-${randomUUID()}`;
  const result = await page.evaluate(
    async ({ marker, projectId, header, version }) => {
      const response = await fetch("/api/v1/delivery/preparations", {
        method: "POST",
        headers: {
          "content-type": "application/json",
          [header]: version,
          "idempotency-key": crypto.randomUUID(),
        },
        body: JSON.stringify({
          policyId: projectId,
          ciRunId: projectId,
          intent: "build",
          command: marker,
        }),
      });
      return { status: response.status, text: await response.text() };
    },
    {
      marker,
      projectId: project.projectId,
      header: CONTROL_API_HEADER,
      version: CONTROL_API_VERSION,
    },
  );
  expect(result.status).toBe(422);
  expect(result.text).not.toContain(marker);
  expect(
    await page.evaluate(() => document.documentElement.scrollWidth - innerWidth),
  ).toBeLessThanOrEqual(1);
  await expect(
    page.getByText(/données persistantes et l’historique restent conservés/),
  ).toBeVisible();
  await expectWholeAction(
    page.getByRole("button", { name: "Confirmer mon identité", exact: true }),
  );
  await expectWholeAction(
    page.getByRole("button", { name: "Préparer l’arrêt des previews expirées", exact: true }),
  );
  await page.screenshot({ path: "artifacts/delivery-mobile.png", fullPage: true });
});

// Read-only stale-security presentation fixture; the confirmation itself uses real browser WebAuthn.
test("T-AC-45 T-AC-51 disables policy commands until fresh passkey confirmation refreshes owner authority", async ({
  page,
}) => {
  await boundProject(page, "Delivery confirmation");
  await page.route("**/api/v1/owner/security", async (route) => {
    const response = await route.fetch();
    const body = await response.json();
    await route.fulfill({ response, json: { ...body, fresh: false } });
  });
  await page.reload();
  const button = page.getByRole("button", { name: "Enregistrer la politique", exact: true });
  await expect(button).toBeDisabled();
  await expect(
    page.getByText(
      "Confirmez votre identité pour modifier une politique ou préparer une livraison.",
      { exact: true },
    ),
  ).toBeVisible();
  await page.unroute("**/api/v1/owner/security");
  await page.getByRole("button", { name: "Confirmer mon identité", exact: true }).click();
  await expect(
    page.getByText("Identité propriétaire confirmée récemment.", { exact: true }),
  ).toBeVisible();
  await expect(button).toBeEnabled();
});

// Synthetic metadata rendering only; actual provider/TTL/absence proof belongs to core and local lab tests.
test("T-AC-49 T-AC-51 hides stale preview URLs at expiry without waiting for physical cleanup or a reload", async ({
  page,
}) => {
  const project = await boundProject(page, "Delivery expiry"),
    expiry = Date.now() + 60_000;
  let reads = 0;
  await page.route("**/api/v1/delivery", async (route) => {
    reads++;
    await route.fulfill({
      headers: { [CONTROL_API_HEADER]: CONTROL_API_VERSION },
      json: {
        source: "configured",
        execution: "configured",
        remoteQualification: "unqualified",
        policies: [],
        preparations: [],
        artifacts: [],
        deployments: [],
        usage: [],
        migrationLocks: [],
        rollbackBlocked: [],
        previews: [
          {
            id: randomUUID(),
            policyId: randomUUID(),
            projectId: project.projectId,
            environmentId: project.projectId,
            pullRequestNumber: 42,
            state: "active",
            dataPolicy: "synthetic-only",
            url: `https://${project.projectId}.preview.fixture.invalid/`,
            expiresAt: new Date(expiry).toISOString(),
            updatedAt: new Date().toISOString(),
          },
        ],
      },
    });
  });
  await page.clock.install();
  await page.goto("/pipelines");
  const link = page.getByRole("link", { name: "Ouvrir la preview vérifiée", exact: true });
  await expect(link).toBeVisible();
  await page.clock.fastForward(61_000);
  await expect(link).toHaveCount(0);
  await expect(page.getByText(/Expirée · arrêt physique à vérifier/)).toBeVisible();
  await expect.poll(() => reads).toBeGreaterThan(1);
});
